    'سوالات-متداول-(FAQ)' => 'Frequently Asked Questions (FAQ)',
    '1.-آیا-اتباع-ایرانی-می‌توانند-در-دبی-ملک-خریداری-کنند؟' => '1. Can foreign nationals buy property in Dubai?',
    'بله.-در-بسیاری-از-مناطق-آزاد-دبی،-اتباع-خارجی-از-جمله-ایرانیان-می‌توانند-مالکیت-100-درصدی-ملک-داشته-باشند.' => 'Yes. In many freehold zones in Dubai, foreign nationals can enjoy 100% full property ownership.',
    '2.-حداقل-مبلغ-لازم-برای-خرید-ملک-در-دبی-چقدر-است؟' => '2. What is the minimum amount required to buy property in Dubai?',
    'قیمت-ملک-بسته-به-موقعیت،-متراژ-و-امکانات-متفاوت-است،-اما-معمولاً-از-حدود-500,000-درهم-آغاز-می‌شود.' => 'Property prices vary depending on location, size, and amenities, but generally start around AED 500,000.',
    '3.-آیا-با-خرید-ملک-می‌توان-اقامت-دبی-را-گرفت؟' => '3. Can buying property lead to obtaining Dubai residency?',
    'بله.-خرید-ملک-با-حداقل-ارزش-مشخص-(معمولاً-750,000-درهم-به-بالا)-می‌تواند-منجر-به-دریافت-اقامت-دو-ساله-قابل-تمدید-امارات-شود.' => 'Yes. Purchasing property with a minimum value (usually AED 750,000+) qualifies you for a renewable residency visa in the UAE.',
    '4.-هزینه‌های-جانبی-خرید-ملک-شامل-چه-مواردی-است؟' => '4. What are the additional costs when buying a property?',
    'تنها-شامل-4-درصد-هزینه-انتقال-سند-میباشد.' => 'It mainly includes a 4% Land Department transfer fee.',
    '5.-آیا-امکان-پرداخت-اقساطی-برای-خرید-ملک-در-دبی-وجود-دارد؟' => '5. Are installment payment plans available for buying property in Dubai?',
    'بله.-بسیاری-از-پروژه‌های-پیش‌فروش-و-برخی-ملک‌های-آماده،-شرایط-پرداخت-اقساطی-متنوعی-ارائه-می‌دهند.' => 'Yes. Many off-plan projects and select ready properties offer flexible installment payment plans.',
    '6.-چرا-باید-از-مشاوران-املاک-دارمکران-کمک-بگیرم؟' => '6. Why should I choose Darmakran Real Estate advisors?',
    'زیرا-تیم-ما-با-آشنایی-کامل-به-بازار-املاک-دبی،-شما-را-از-ابتدا-تا-انتهای-مسیر-همراهی-کرده-و-بهترین-پیشنهادات-را-مطابق-با-نیازتان-ارائه-می‌دهد.' => 'Because our team has comprehensive expertise in the Dubai real estate market and guides you seamlessly from start to finish with tailored solutions.',
    '7.-مدت-زمان-انجام-مراحل-خرید-ملک-در-دبی-چقدر-است؟' => '7. How long does the property buying process take in Dubai?',
    'در-صورت-آماده-بودن-مدارک-و-توافق-طرفین،-فرآیند-خرید-ملک-در-دبی-فقط-1-روز-زمان-می‌برد.' => 'With ready documentation and mutual consent, the property transaction process in Dubai can be completed in just 1 day.',
    '8.-آیا-مالکیت-ملک-در-دبی-دائمی-است؟' => '8. Is property ownership in Dubai permanent?',
    'بله،-در-مناطق-فری‌هولد-(Freehold)-مالکیت-کامل-و-دائمی-به-خریدار-داده-می‌شود-و-قابل-انتقال-به-وراث-نیز-هست.' => 'Yes, in Freehold areas full permanent ownership is granted and can be inherited.',
    '9.-آیا-خرید-ملک-در-دبی-نیاز-به-حضور-فیزیکی-دارد؟' => '9. Does buying property in Dubai require physical presence?',
    'خیر.-امکان-خرید-ملک-به‌صورت-غیرحضوری-و-از-راه-دور-با-اعطای-وکالت-قانونی-وجود-دارد.' => 'No. Properties can be purchased remotely via Power of Attorney (POA).',
    '10.-آیا-امکان-اجاره-دادن-ملک-خریداری‌شده-وجود-دارد؟' => '10. Can purchased properties be rented out?',
    'بله،-خریدار-می‌تواند-ملک-خود-را-به-صورت-کوتاه‌مدت-یا-بلندمدت-اجاره-دهد-و-از-درآمد-ارزی-بهره‌مند-شود.' => 'Yes, owners can lease their property short-term or long-term for attractive rental yields.',
    '11.-آیا-مالیات-سالانه-بر-املاک-در-دبی-وجود-دارد؟' => '11. Are there annual property taxes in Dubai?',
    'خیر.-در-حال-حاضر-در-دبی-مالیات-بر-درآمد-یا-مالیات-سالانه-ملک-دریافت-نمی‌شود،-اما-هزینه‌هایی-مانند-هزینه-خدمات-ساختمان-(service-charge)-وجود-دارد.' => 'No. Currently there are no annual property or income taxes in Dubai, though standard building service charges apply.',
    '12.-تفاوت-بین-مناطق-فری‌هولد-و-لیزهولد-چیست؟' => '12. What is the difference between Freehold and Leasehold areas?',
    'در-مناطق-فری‌هولد-مالکیت-کامل-به-خریدار-داده-می‌شود،-اما-در-مناطق-لیزهولد-مالکیت-برای-مدت-معینی-(مثلاً-99-سال)-در-اختیار-خریدار-قرار-می‌گیرد.' => 'In Freehold areas you gain 100% full ownership forever, while Leasehold grants rights for a fixed term (e.g. 99 years).',
    '13.-آیا-برای-خرید-ملک-باید-حساب-بانکی-در-امارات-داشته-باشم؟' => '13. Is a UAE bank account mandatory to buy property?',
    'خیر.-داشتن-حساب-بانکی-الزامی-نیست،-اما-برای-دریافت-اقامت-یا-انجام-برخی-پرداخت‌ها،-افتتاح-حساب-بانکی-توصیه-می‌شود.' => 'No. A local bank account is not strictly mandatory to buy, though recommended for residency and recurring payments.',
    '14.-آیا-امکان-دریافت-وام-برای-خرید-ملک-در-دبی-وجود-دارد؟' => '14. Can foreigners get a mortgage for property in Dubai?',
    'بله.-اتباع-خارجی-می‌توانند-با-شرایط-خاص-از-بانک‌های-اماراتی-یا-موسسات-مالی-معتبر-وام-مسکن-دریافت-کنند.' => 'Yes. Foreign nationals can qualify for home loans from UAE banks under specific conditions.',
    '15.-آیا-دارمکران-فقط-در-دبی-فعالیت-می‌کند-یا-در-سایر-امارات-هم-خدمات-دارد؟' => '15. Does Darmakran operate only in Dubai or in other emirates too?',
    'در-حال-حاضر-تمرکز-ما-بر-املاک-دبی-است،-اما-در-صورت-نیاز،-پروژه‌ها-و-مشاوره‌هایی-در-سایر-مناطق-مانند-شارجه-و-ابوظبی-و-سایر-امارت-ها-نیز-ارائه-می‌دهیم.' => 'Our main focus is Dubai real estate, though we also provide consultation and properties across Abu Dhabi, Sharjah, and other emirates.',
    '16.-آیا-دارمکران-خدمات-پس-از-خرید-هم-ارائه-می‌دهد؟' => '16. Does Darmakran offer post-purchase services?',
    'بله.-ما-در-دارمکران-خدماتی-مانند-مدیریت-ملک،-اجاره-دادن،-نظارت-بر-تعمیرات-و-تمدید-اقامت-را-نیز-به-مشتریان-عزیز-ارائه-می‌دهیم.' => 'Yes. We provide property management, tenant placement, maintenance supervision, and visa renewal assistance.',
    '17.-چگونه-می‌توانم-با-کارشناسان-دارمکران-مشاوره-رایگان-داشته-باشم؟' => '17. How can I get a free consultation with Darmakran experts?',
    'از-طریق-فرم-تماس-در-سایت،-واتساپ-یا-تماس-مستقیم-می‌توانید-با-ما-ارتباط-بگیرید-و-مشاوره-اولیه-کاملاً-رایگان-دریافت-کنید.' => 'You can contact us via our website form, WhatsApp, or direct call (+971 55 762 1019) for a free initial consultation.',
    '18.-دارمکران-چه-نوع-املاکی-را-ارائه-می‌دهد؟' => '18. What types of properties does Darmakran offer?',
    'دارمکران-در-زمینه-فروش-آپارتمان‌،-ویلا،-واحدهای-لوکس،-املاک-تجاری،-پیش‌فروش-و-پروژه‌های-در-حال-ساخت-در-مناطق-مختلف-دبی-فعالیت-دارد.' => 'We offer luxury apartments, villas, commercial spaces, and off-plan developmental projects across Dubai.',
    'املاک-فروش-فوری' => 'Urgent Sale Properties',
    'چرا-دارمکران-برای-شما-انتخاب-خوبی-است؟' => 'Why is Darmakran a good choice for you?',
    'املاک-دارمکران-یک-بنگاه-معاملات-ملکی-در-دبی-است-که-به‌طور-تخصصی-خدمات-خرید،-فروش-و-اجاره-ملک-را-به-سرمایه‌گذاران-ایرانی-ارائه-می‌دهد.-با-آشنایی-کامل-با-بازار-املاک-امارات،-املاک-دارمکران-مسیر-مطمئنی-برای-سرمایه‌گذاری،-خرید-خانه-و-دریافت-اقامت-در-دبی-فراهم-می‌کند.' => 'Darmakran Real Estate is a property agency in Dubai that specializes in providing property buying, selling, and renting services to Iranian investors. With complete familiarity with the UAE real estate market, Darmakran Real Estate provides a reliable path for investment, buying a home, and obtaining residency in Dubai.',
    'مالک-هستید؟' => 'Are you a property owner?',
    'هر-کجای-کشور-امارات-که-ملکی-برای-فروش-دارید-می-تونید-با-چند-کلیک-ساده-ملکتان-را-به-صورت-رایگان-در-دارمکران-آگهی-و-در-سریع-ترین-زمان-ممکن-معامله-کنید' => 'Wherever in the UAE you have a property for sale, you can list it for free on Darmakran with a few simple clicks and trade it as quickly as possible.',
    'ثبت-رایگان-آگهی' => 'Free Property Listing',
    'املاک-اکازیون' => 'Special Offer Properties',
