    'محاسبه' => 'N/A',
    'حق کمیسیون مشاورین املاک به کارمزدی گفته می‌شود که مشاورین به‌عنوان دستمزد دریافت می‌کنند و در قدیم بنا به اختیار خریدار و فروشنده به آژانس املاک پرداخت می‌شد، اما از سال ۱۳۷۹ بر اساس قانون فرمول خاصی برای محاسبه حق کمیسیون برای انواع فعالیت های تجاری در زمینه مسکن مانند خرید، فروش، رهن و اجاره ی انواع املاک تجاری، مسکونی و اداری دریافت میشود. پرداخت کمیسیون یکی از مفاد و قوانین معاملاتی در کشور است و طرفین معامله ملزم به پرداخت آن هستند."کمیسیون املاک" توسط فروشنده و خریدار یا مؤجر و مستأجر به مشاوران املاک پرداخت می‌شود. با توجه به بازار املاک، این مبلغ بر اساس مصوبه صنف شهر مورد نظر برای هر معامله بر اساس فاکتورهای خاصی محاسبه می‌شود. مشاورین املاک موظفند، بر اساس تعرفه‌ای که هر سال از سوی' => 'Agent Properties to ‌ Agent to‌Title Receive ‌ in to Buy Sale to Properties Reject ‌completed from years 1379 for for Active Commercial in Land Buy Sale Mortgage / Deposit Rent Properties Commercial Residential Office / Administrative Receive . Reject from in is to Reject ." Properties" Sale Buy to Agent Properties Reject ‌. with to Properties City Reject for ‌. Agent Properties ‌ years from',
    'حق-کمیسیون-مشاورین-املاک-به-کارمزدی-گفته-می‌شود-که-مشاورین-به‌عنوان-دستمزد-دریافت-می‌کنند-و-در-قدیم-بنا-به-اختیار-خریدار-و-فروشنده-به-آژانس-املاک-پرداخت-می‌شد،-اما-از-سال-۱۳۷۹-بر-اساس-قانون-فرمول-خاصی-برای-محاسبه-حق-کمیسیون-برای-انواع-فعالیت-های-تجاری-در-زمینه-مسکن-مانند-خرید،-فروش،-رهن-و-اجاره-ی-انواع-املاک-تجاری،-مسکونی-و-اداری-دریافت-میشود.-پرداخت-کمیسیون-یکی-از-مفاد-و-قوانین-معاملاتی-در-کشور-است-و-طرفین-معامله-ملزم-به-پرداخت-آن-هستند."کمیسیون-املاک"-توسط-فروشنده-و-خریدار-یا-مؤجر-و-مستأجر-به-مشاوران-املاک-پرداخت-می‌شود.-با-توجه-به-بازار-املاک،-این-مبلغ-بر-اساس-مصوبه-صنف-شهر-مورد-نظر-برای-هر-معامله-بر-اساس-فاکتورهای-خاصی-محاسبه-می‌شود.-مشاورین-املاک-موظفند،-بر-اساس-تعرفه‌ای-که-هر-سال-از-سوی' => '--Agent-Properties-to---‌--Agent-to‌Title--Receive-‌--in---to--Buy--Sale-to--Properties-Reject-‌completed--from-years-1379------for----for--Active--Commercial-in-Land---Buy-Sale-Mortgage / Deposit--Rent---Properties-Commercial-Residential--Office / Administrative-Receive-.-Reject---from-----in--is-----to-Reject--."-Properties"--Sale--Buy-----to-Agent-Properties-Reject-‌.-with--to--Properties-------City-Reject--for--------‌.-Agent-Properties----‌---years-from-',
    ': این فرمول کشوری است و ملاک هر شهرستان، نامه اتحادیه مشاورین املاک آن شهرستان است که ممکن است با فرمول کشوری کمی تفاوت داشته باشد.' => ': is City Name Agent Properties City is is with .',
    ':-این-فرمول-کشوری-است-و-ملاک-هر-شهرستان،-نامه-اتحادیه-مشاورین-املاک-آن-شهرستان-است-که-ممکن-است-با-فرمول-کشوری-کمی-تفاوت-داشته-باشد.' => ':----is----City-Name--Agent-Properties--City-is---is-with------.',
    'همانطور که می دانید در ایران، خرید و یا فروش یک ملک یا اجاره کردن آن می‌تواند یک سرمایه‌گذاری مطمئن برای خانواده باشد، چرا که هم نرخ مسکن دائما رو به افزایش است و هم با خرید یک منزل می‌توان آن را به منبعی برای کسب درآمد تبدیل کرد. بنابراین هیچ‌کس دوست ندارد در این زمینه بی‌گدار به آب زده و پس‌انداز و سرمایه خود را در خانه‌ای با مشکلات حقوقی و فنی فراوان هدر دهد. در عین حال هیچ انسانی مایل نیست بخش اعظمی از حقوق ماهیانه خود را صرف پرداخت اجاره ملکی کند که قیمت آن از استانداردهای روز بازار بالاتر است یا مطلوبیتی برای اهالی خانه ندارد.' => 'in Buy Sale Property Rent Reject ‌ ‌ for to is with Buy ‌ to for Reject. ‌ Reject in Land ‌ to ‌ in ‌ with . in is not from Reject Rent Property Price from Emirate / ProvinceReject is for Reject.',
    'همانطور-که-می-دانید-در-ایران،-خرید-و-یا-فروش-یک-ملک-یا-اجاره-کردن-آن-می‌تواند-یک-سرمایه‌گذاری-مطمئن-برای-خانواده-باشد،-چرا-که-هم-نرخ-مسکن-دائما-رو-به-افزایش-است-و-هم-با-خرید-یک-منزل-می‌توان-آن-را-به-منبعی-برای-کسب-درآمد-تبدیل-کرد.-بنابراین-هیچ‌کس-دوست-ندارد-در-این-زمینه-بی‌گدار-به-آب-زده-و-پس‌انداز-و-سرمایه-خود-را-در-خانه‌ای-با-مشکلات-حقوقی-و-فنی-فراوان-هدر-دهد.-در-عین-حال-هیچ-انسانی-مایل-نیست-بخش-اعظمی-از-حقوق-ماهیانه-خود-را-صرف-پرداخت-اجاره-ملکی-کند-که-قیمت-آن-از-استانداردهای-روز-بازار-بالاتر-است-یا-مطلوبیتی-برای-اهالی-خانه-ندارد.' => '----in--Buy---Sale--Property--Rent-Reject--‌--‌--for----------to--is---with-Buy---‌---to--for----Reject.--‌--Reject-in--Land-‌-to----‌-----in-‌-with-------.-in------is not---from------Reject-Rent-Property---Price--from-Emirate / ProvinceReject----is---for---Reject.',
    'مجموعه این حساسیت‌ها باعث شده تا پیدا کردن ملکی که از نظر موقعیت جغرافیایی، مصالح ساخت ملک، اصول مهندسی و سایر فاکتورها بهترین بازار باشد، به امری پیچیده و دشوار و نیازمند تخصص تبدیل شود. شاید بتوان به جرات گفت پیدا کردن چنین ملکی خود یک کار تمام‌ وقت است که به تمام انرژی، تمرکز و صبر شما احتیاج دارد. به همین دلیل است که در بسیاری از کشورهای دنیا شغل مهمی با عنوان “مشاورین املاک” شکل گرفته. این افراد در ازای دریافت حق العمل، خدماتی را در حوزه ملک و مسکن به شما ارائه می‌دهند و با توجه به گستردگی و پیچیدگی های این کار بهتر است به یک دپارتمان املاک معتبر، مراجعه کنید. که در این امر دپارتمان املاک کومه با دارا بودن مشاورین متخصص در زمینه های مختلف ملکی می تواند همچون نیاز های ملکی شما را آسان، سریع و مطمئن مرتفع نماید.' => '‌ Reject Property from Property to . to Reject Property ‌ is to Reject. to is in from with Title “Agent Properties” . in Receive in Property to ‌ with to Reject is to Properties . in Properties with Agent in Land Property Property .',
    'مجموعه-این-حساسیت‌ها-باعث-شده-تا-پیدا-کردن-ملکی-که-از-نظر-موقعیت-جغرافیایی،-مصالح-ساخت-ملک،-اصول-مهندسی-و-سایر-فاکتورها-بهترین-بازار-باشد،-به-امری-پیچیده-و-دشوار-و-نیازمند-تخصص-تبدیل-شود.-شاید-بتوان-به-جرات-گفت-پیدا-کردن-چنین-ملکی-خود-یک-کار-تمام‌-وقت-است-که-به-تمام-انرژی،-تمرکز-و-صبر-شما-احتیاج-دارد.-به-همین-دلیل-است-که-در-بسیاری-از-کشورهای-دنیا-شغل-مهمی-با-عنوان-“مشاورین-املاک”-شکل-گرفته.-این-افراد-در-ازای-دریافت-حق-العمل،-خدماتی-را-در-حوزه-ملک-و-مسکن-به-شما-ارائه-می‌دهند-و-با-توجه-به-گستردگی-و-پیچیدگی-های-این-کار-بهتر-است-به-یک-دپارتمان-املاک-معتبر،-مراجعه-کنید.-که-در-این-امر-دپارتمان-املاک-کومه-با-دارا-بودن-مشاورین-متخصص-در-زمینه-های-مختلف-ملکی-می-تواند-همچون-نیاز-های-ملکی-شما-را-آسان،-سریع-و-مطمئن-مرتفع-نماید.' => '--‌-----Reject-Property--from------Property---------to---------.---to----Reject--Property----‌--is--to--------Reject.-to---is--in--from-----with-Title-“Agent-Properties”--.---in--Receive-----in--Property---to---‌--with--to-Reject-------is-to---Properties---.--in----Properties--with---Agent--in-Land---Property------Property--------.',
