    'حال می بایست برای معرفی اقامتگاه خود به گردشگران, یک نمایه (پروفایل) برای اقامتگاه خود ایجاد کنید‎.‎' => 'for to Reject, (File) for Create / Add ‎.‎',
    'حال-می-بایست-برای-معرفی-اقامتگاه-خود-به-گردشگران,-یک-نمایه-(پروفایل)-برای-اقامتگاه-خود-ایجاد-کنید‎.‎' => '---for----to-Reject,---(File)-for---Create / Add-‎.‎',
    'در ‎نمایه اقامتگاه‎, شما می بایست مشخصات دقیق منزل و امکانات قابل استفاده توسط میهمانان را مشخص کنید. ‎عکسهایی واضح و جدید‎ ‏از اقامتگاه خود فراهم نموده و‎ Upload ‎کنید, همچنین ‎نرخ اجاره بها و تقویم اجاره‎ منزل خود را نیز تنظیم کنید . در آخر مقرراتی که می باید توسط میهمانان رعایت شود را نیز مشخص کنید. ‎نمایه اقامتگاه شما درواقع بیانگر مشخصات و ویژگیهای واقعی ‏منزل شما برای گردشگران علاقه مند خواهد بود‎.‎' => 'in ‎ ‎, . ‎Photo New‎ ‏from ‎ Upload ‎, ‎ Rent Rent‎ . in . ‎ ‏ for Reject ‎.‎',
    'در-‎نمایه-اقامتگاه‎,-شما-می-بایست-مشخصات-دقیق-منزل-و-امکانات-قابل-استفاده-توسط-میهمانان-را-مشخص-کنید.-‎عکسهایی-واضح-و-جدید‎-‏از-اقامتگاه-خود-فراهم-نموده-و‎-Upload-‎کنید,-همچنین-‎نرخ-اجاره-بها-و-تقویم-اجاره‎-منزل-خود-را-نیز-تنظیم-کنید-.-در-آخر-مقرراتی-که-می-باید-توسط-میهمانان-رعایت-شود-را-نیز-مشخص-کنید.-‎نمایه-اقامتگاه-شما-درواقع-بیانگر-مشخصات-و-ویژگیهای-واقعی-‏منزل-شما-برای-گردشگران-علاقه-مند-خواهد-بود‎.‎' => 'in-‎-‎,---------------.-‎Photo---New‎-‏from-----‎-Upload-‎,--‎-Rent----Rent‎-------.-in-------------.-‎---------‏--for-Reject----‎.‎',
    'شما در کنار ثبت مشخصات و امکانات اقامتگاه خود, مواردی همچون ‎ اجاره بها و مقررات منزل‎ را نیز تعیین می کنید. سپس نمایه اقامتگاه شما در وبسایت ‎منتشر‎ می شود و برای مسافرین و گردشگران به نمایش درمی آید. گردشگران با جستجو در وبسایت, در صورتی که مشخصات اقامتگاه شما را مناسب نیاز خود بیابند درصورت قبول مقررات منزل, برای اجاره اقامتگاه در بازه زمانی ‏مد نظر با گیلندملک تماس میگیرند.‏ درصورت تایید شما و پرداخت صورتحساب توسط مهمان، رزرو قطعی می شود.' => 'in Submit , Reject ‎ Rent ‎ . in ‎‎ for Reject to View / Show . Reject with Search in , in , for Rent in Time ‏ with Property .‏ Confirm Reject .',
    'شما-در-کنار-ثبت-مشخصات-و-امکانات-اقامتگاه-خود,-مواردی-همچون-‎-اجاره-بها-و-مقررات-منزل‎-را-نیز-تعیین-می-کنید.-سپس-نمایه-اقامتگاه-شما-در-وبسایت-‎منتشر‎-می-شود-و-برای-مسافرین-و-گردشگران-به-نمایش-درمی-آید.-گردشگران-با-جستجو-در-وبسایت,-در-صورتی-که-مشخصات-اقامتگاه-شما-را-مناسب-نیاز-خود-بیابند-درصورت-قبول-مقررات-منزل,-برای-اجاره-اقامتگاه-در-بازه-زمانی-‏مد-نظر-با-گیلندملک-تماس-میگیرند.‏-درصورت-تایید-شما-و-پرداخت-صورتحساب-توسط-مهمان،-رزرو-قطعی-می-شود.' => '-in--Submit-----,-Reject--‎-Rent----‎-----.-----in--‎‎----for---Reject-to-View / Show--.-Reject-with-Search-in-,-in--------------,-for-Rent--in--Time-‏--with-Property--.‏--Confirm---Reject-------.',
    'امکانات تعبیه شده در سایت بگونه ای ست تا پس از صرف وقت کافی برای ثبت و انتشار اقامتگاه خود, بتوانید تمام مراحل میزبانی را طی فرایندی ساده و کاربردی و با صرف زمانی اندک, برای شما امکانپذیر نماید. با این وجود, ما از لحظه ثبت‌نام، ثبت اقامتگاه و آغاز میزبانی, در کنارتان هستیم و شما را در این مسیر هیجان انگیز همراهی میکنیم.' => 'in from for Submit , Reject with Time , for . with , from Submit‌Name Submit , in in .',
    'امکانات-تعبیه-شده-در-سایت-بگونه-ای-ست-تا-پس-از-صرف-وقت-کافی-برای-ثبت-و-انتشار-اقامتگاه-خود,-بتوانید-تمام-مراحل-میزبانی-را-طی-فرایندی-ساده-و-کاربردی-و-با-صرف-زمانی-اندک,-برای-شما-امکانپذیر-نماید.-با-این-وجود,-ما-از-لحظه-ثبت‌نام،-ثبت-اقامتگاه-و-آغاز-میزبانی,-در-کنارتان-هستیم-و-شما-را-در-این-مسیر-هیجان-انگیز-همراهی-میکنیم.' => '---in-------from----for-Submit----,----------Reject--with--Time-,-for---.-with--,--from--Submit‌Name-Submit----,-in------in------.',
