    'در صورتی که رزرو, بیش از 5 روز کامل از تاریخ ورود لغو گردد, 10% صورتحساب به میزبان پرداخت می‏شود. درصورت لغو کمتر از 5 روز به تاریخ ورود، اجاره شب اول بعلاوه 40 درصد از شب‌های باقیمانده به میزبان پرداخت می شود.' => 'in , from 5 from Date Login Reject, 10% to Reject ‏. m² from 5 to Date Login Rent 40 from ‌ to Reject .',
    'در-صورتی-که-رزرو,-بیش-از-5-روز-کامل-از-تاریخ-ورود-لغو-گردد,-10%-صورتحساب-به-میزبان-پرداخت-می‏شود.-درصورت-لغو-کمتر-از-5-روز-به-تاریخ-ورود،-اجاره-شب-اول-بعلاوه-40-درصد-از-شب‌های-باقیمانده-به-میزبان-پرداخت-می-شود.' => 'in---,--from-5---from-Date-Login--Reject,-10%--to--Reject-‏.---m²-from-5--to-Date-Login-Rent----40--from-‌--to--Reject--.',
    'در صورتی که رزرو, بیش از 3 روز کامل از تاریخ ورود لغو گردد, میزبان دریافتی ندارد. درصورت لغو کمتر از 3 روز به تاریخ ورود، اجاره شب اول به میزبان پرداخت می شود.' => 'in , from 3 from Date Login Reject, Receive Reject. m² from 3 to Date Login Rent to Reject .',
    'در-صورتی-که-رزرو,-بیش-از-3-روز-کامل-از-تاریخ-ورود-لغو-گردد,-میزبان-دریافتی-ندارد.-درصورت-لغو-کمتر-از-3-روز-به-تاریخ-ورود،-اجاره-شب-اول-به-میزبان-پرداخت-می-شود.' => 'in---,--from-3---from-Date-Login--Reject,--Receive-Reject.---m²-from-3--to-Date-Login-Rent---to--Reject--.',
    'در صورتی که رزرو، بیش از ۲۴ ساعت از تاریخ ورود لغو گردد میزبان دریافتی ندارد. درصورت لغو کمتر از 24 ساعت به تاریخ ورود، اجاره شب اول به میزبان پرداخت می شود.' => 'in from 24 from Date Login Reject Receive Reject. m² from 24 to Date Login Rent to Reject .',
    'در-صورتی-که-رزرو،-بیش-از-۲۴-ساعت-از-تاریخ-ورود-لغو-گردد-میزبان-دریافتی-ندارد.-درصورت-لغو-کمتر-از-24-ساعت-به-تاریخ-ورود،-اجاره-شب-اول-به-میزبان-پرداخت-می-شود.' => 'in-----from-24--from-Date-Login--Reject--Receive-Reject.---m²-from-24--to-Date-Login-Rent---to--Reject--.',
