    'املاک گیلان، خرید ملک در شمال' => 'Properties Buy Property in',
    'املاک-گیلان،-خرید-ملک-در-شمال' => 'Properties--Buy-Property-in-',
    'گیلند ملک یک تیم با تجربه واقعی و متخصص در زمینه صنعت ملکی می باشد که به شما این امکان را می دهد بهترین خدمات را در خرید، فروش، و سرمایه گذاری در املاک و مستغلات دریافت کنید.' => 'Property with in Land Property to in Buy Sale in Properties Real Estate Receive .',
    'گیلند-ملک-یک-تیم-با-تجربه-واقعی-و-متخصص-در-زمینه-صنعت-ملکی-می-باشد-که-به-شما-این-امکان-را-می-دهد-بهترین-خدمات-را-در-خرید،-فروش،-و-سرمایه-گذاری-در-املاک-و-مستغلات-دریافت-کنید.' => '-Property---with-----in-Land--Property----to----------in-Buy-Sale----in-Properties--Real Estate-Receive-.',
    'گیلند ملک با داشتن دانش گسترده در زمینه قوانین ملکی و مشاوره تخصصی ، به شما اطمینان می دهد که تمام مراحل خرید یا فروش ملک خود را بدون هیچ ابهامی و بسیار واضح وروشن و در کمال آرامش انجام دهید.' => 'Property with Reject in Land Property Agent to Buy Sale Property in .',
    'گیلند-ملک-با-داشتن-دانش-گسترده-در-زمینه-قوانین-ملکی-و-مشاوره-تخصصی-،-به-شما-اطمینان-می-دهد-که-تمام-مراحل-خرید-یا-فروش-ملک-خود-را-بدون-هیچ-ابهامی-و-بسیار-واضح-وروشن-و-در-کمال-آرامش-انجام-دهید.' => '-Property-with---Reject-in-Land--Property--Agent---to--------Buy--Sale-Property-----------in----.',
    'گیلند ملک با توجه به نیازها و مهارت های شما و با شناخت دقیق از بازار ملکی ، به شما راهنمایی حرفه ای می دهد تا بهترین تصمیم را در مورد خرید یا فروش ملک خود بگیرید.' => 'Property with to with from Property to in Reject Buy Sale Property .',
    'گیلند-ملک-با-توجه-به-نیازها-و-مهارت-های-شما-و-با-شناخت-دقیق-از-بازار-ملکی-،-به-شما-راهنمایی-حرفه-ای-می-دهد-تا-بهترین-تصمیم-را-در-مورد-خرید-یا-فروش-ملک-خود-بگیرید.' => '-Property-with--to-------with---from--Property--to-----------in-Reject-Buy--Sale-Property--.',
    'گیلند ملک با داشتن رابطه ای صمیمانه و دوستانه با کارشناسان ملکی ، توسعه دهندگان و سازندگان و سایر عوامل صنعت ملک ، به شما کمک می کند تا بهترین به معاملات ، فرصت ها و نتایج ممکن دست پیدا کنید.' => 'Property with with Expert / Consultant Property Property to to .',
